def solve(inputs):
    """
    Updates an existing pet in the Swagger Petstore (OpenAPI 3) service.

    Args:
        inputs (dict): A dictionary containing:
            - new_resource_id (str): The new ID for the pet.
            - new_name (str): The new name for the pet.
            - new_photo_links (list of str or None): New photo URLs for the pet.
            - credential (dict): Caller-supplied credentials (e.g., API key, Bearer token).

    Returns:
        int or None: The HTTP status code from the response, or None if the response is empty.

    Raises:
        Exception: If the HTTP response indicates an unsuccessful status.
    """
    base_url = "https://petstore3.swagger.io/api/v3"  # Standard OpenAPI 3 Petstore URL

    endpoint = f"{base_url}/pet/{inputs['new_resource_id']}"

    payload = {
        "id": inputs["new_resource_id"],
        "name": inputs["new_name"],
        "photoUrls": inputs["new_photo_links"] if inputs["new_photo_links"] is not None else []
    }

    headers = {}
    if "credential" in inputs:
        # Assuming credential contains a 'token' or similar for Bearer auth, or 'api_key'
        if isinstance(inputs["credential"], dict):
            if "token" in inputs["credential"]:
                headers["Authorization"] = f"Bearer {inputs['credential']['token']}"
            elif "api_key" in inputs["credential"]:
                headers["X-API-Key"] = inputs["credential"]["api_key"]
        else:
            # Fallback if credential is a string (e.g., direct API key)
            if inputs["credential"].startswith("Bearer "):
                headers["Authorization"] = inputs["credential"]
            elif inputs["credential"].startswith("X-API-Key"):
                headers["X-API-Key"] = inputs["credential"].split(":", 1)[1].strip()

    response = requests.put(endpoint, json=payload, headers=headers)

    if response.status_code >= 400:
        raise Exception(f"Failed to update pet. Status code: {response.status_code}, Response: {response.text}")

    return None if response.text.strip() == "" else response.status_code

