def solve(inputs):
    """
    Updates a pet in the Swagger Petstore (OpenAPI 3 service) with form data.

    Args:
        inputs (dict): A dictionary containing:
            - 'pet_identifier': ID of the pet to update.
            - 'name': New name for the pet.
            - 'status': New status for the pet.
            - 'credential': Caller-supplied credential (e.g., API key or token).

    Returns:
        dict or None: The decoded JSON response if successful and non-empty, 
                      None if the response is empty but successful.

    Raises:
        Exception: If the HTTP response indicates an unsuccessful status code.
    """
    pet_identifier = inputs['pet_identifier']
    name = inputs['name']
    status = inputs['status']
    credential = inputs['credential']

    # Swagger Petstore typically uses /pet/{id} for updates, with PUT method.
    # Form data is sent as application/x-www-form-urlencoded.
    url = "https://petstore.swagger.io/v2/pet"

    payload = {
        'name': name,
        'status': status
    }

    headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    }

    # Depending on the credential type (e.g., API key), we might need to include it in headers or query params.
    # Assuming 'credential' is an API Key, we'll add it to the header.
    if isinstance(credential, str):
        headers['X-API-Key'] = credential

    try:
        response = requests.put(url, data=payload, headers=headers)

        if response.status_code == 200 or response.status_code == 204:
            # For 204 No Content, there is no JSON body to decode.
            if response.content:
                return response.json()
            else:
                return None
        elif response.status_code >= 400:
            raise Exception(f"Failed to update pet. HTTP status code: {response.status_code}, Response: {response.text}")
        else:
            # For other successful codes (like 201 Created), try to decode JSON if present.
            if response.content:
                return response.json()
            else:
                return None
    except requests.exceptions.RequestException as e:
        raise Exception(f"Request failed: {str(e)}")

